import { readdir, stat } from 'node:fs/promises';import { join } from 'node:path';async function files(dir){const entries=await readdir(dir,{withFileTypes:true});return(await Promise.all(entries.map(entry=>entry.isDirectory()?files(join(dir,entry.name)):[join(dir,entry.name)]))).flat()}const assets=(await files('dist/assets')).filter(file=>/\.(css|js)$/.test(file)),bytes=(await Promise.all(assets.map(async file=>(await stat(file)).size))).reduce((total,value)=>total+value,0),budget=180000;if(bytes>budget)throw new Error(`Static CSS + JS is ${bytes} bytes, over the ${budget}-byte budget.`);console.log(`Static CSS + JavaScript: ${bytes.toLocaleString()} bytes (budget ${budget.toLocaleString()} bytes).`);
